-- NEXRIDES RUSH 88 | Procedural display model, not a drivable chassis.
-- Paste into the Studio Command Bar or a Script in ServerScriptService and Run.
-- Shared geometry with car.html. Metres -> 4 studs. Front is -X, up is +Y.
-- All components anchored. Only the floor is collidable. No external assets.
local SCALE = 4
local ORIGIN = Vector3.new(0, 0, 0)
local root = Instance.new("Model")
root.Name = "NEXRIDES_Car_88"
local groups = {}
local function folder(path)
 local parent = root
 local key = ""
 for name in string.gmatch(path, "[^/]+") do
  key = key .. "/" .. name
  if not groups[key] then
   local group = Instance.new("Model")
   group.Name = name; group.Parent = parent; groups[key] = group
  end
  parent = groups[key]
 end
 return parent
end
for _,name in ipairs({"Body","Front","Rear","Hood","Fenders","Wheels/FrontLeft","Wheels/FrontRight","Wheels/RearLeft","Wheels/RearRight","Interior","Windows","Lights","Spoiler","Exhaust","Decals"}) do folder(name) end
local colors = {white=Color3.fromRGB(244,244,238),carbon=Color3.fromRGB(17,21,26),black=Color3.fromRGB(8,10,13),dark=Color3.fromRGB(41,43,48),rubber=Color3.fromRGB(18,19,21),red=Color3.fromRGB(231,23,51),metal=Color3.fromRGB(160,167,172),glass=Color3.fromRGB(52,73,87),light=Color3.fromRGB(215,239,255),redlight=Color3.fromRGB(255,22,53)}
local function vec(p) return Vector3.new(p[1],p[2],p[3])*SCALE+ORIGIN end
local function parentFor(n)
 local path = string.match(n,"^(.*)/[^/]+$")
 return folder(path or "Body")
end
local function part(n, size, cf, mat, class)
 local p=Instance.new(class or "Part")
 p.Name=string.match(n,"[^/]+$") or n
 p.Size=size; p.CFrame=cf; p.Color=colors[mat] or colors.white
 p.Material=Enum.Material.SmoothPlastic
 if mat=="metal" then p.Material=Enum.Material.Metal; p.Reflectance=.25 end
 if mat=="glass" then p.Material=Enum.Material.Glass; p.Transparency=.58; p.Reflectance=.12 end
 if mat=="rubber" then p.Material=Enum.Material.SmoothPlastic end
 if mat=="light" or mat=="redlight" then p.Material=Enum.Material.Neon end
 p.Anchored=true; p.CanCollide=n=="Body/Floor"; p.CanTouch=false; p.CanQuery=true
 p.TopSurface=Enum.SurfaceType.Smooth; p.BottomSurface=Enum.SurfaceType.Smooth
 p.CastShadow=mat~="glass"; p.Parent=parentFor(n)
 return p
end
local function rod(n,a,b,r,m)
 local d=b-a
 if d.Magnitude<.00001 then return end
 local x=d.Unit
 local ref=math.abs(x.Y)>.99 and Vector3.zAxis or Vector3.yAxis
 local z=x:Cross(ref).Unit
 local y=z:Cross(x).Unit
 local p=part(n,Vector3.new(d.Magnitude,r*2*SCALE,r*2*SCALE),CFrame.fromMatrix((a+b)/2,x,y,z),m)
 p.Shape=Enum.PartType.Cylinder
 return p
end
-- Two right wedges tessellate each arbitrary triangle exactly; no uploaded meshes.
local function triangle(n,a,b,c,m)
 local ab,ac,bc=b-a,c-a,c-b
 local ab2,ac2,bc2=ab:Dot(ab),ac:Dot(ac),bc:Dot(bc)
 if ab2>ac2 and ab2>bc2 then c,a=a,c elseif ac2>bc2 and ac2>ab2 then a,b=b,a end
 ab,ac,bc=b-a,c-a,c-b
 if bc.Magnitude<.00001 or ac:Cross(ab).Magnitude<.00001 then return end
 local right=ac:Cross(ab).Unit
 local back=bc.Unit
 local up=bc:Cross(right).Unit
 local height=math.abs(ab:Dot(up))
 local len1=math.abs(ab:Dot(back));local len2=math.abs(ac:Dot(back))
 if height<.00001 then return end
 if len1>.00001 then part(n,Vector3.new(.012,height,len1),CFrame.fromMatrix((a+b)/2,right,up,back),m,"WedgePart") end
 if len2>.00001 then part(n,Vector3.new(.012,height,len2),CFrame.fromMatrix((a+c)/2,-right,up,-back),m,"WedgePart") end
end
