for _,s in ipairs(specs) do
 if s.t=="box" then
  part(s.n,Vector3.new(s.d[1],s.d[2],s.d[3])*SCALE,CFrame.new(vec(s.p))*CFrame.Angles(s.r[1],s.r[2],s.r[3]),s.m)
 elseif s.t=="rod" then rod(s.n,vec(s.a),vec(s.b),s.r,s.m)
 elseif s.t=="face" then
  for i=2,#s.v-1 do triangle(s.n,vec(s.v[1]),vec(s.v[i]),vec(s.v[i+1]),s.m) end
 elseif s.t=="ring" then
  local center=vec(s.p)
  local front=string.sub(s.n,1,6)=="Lights"
  local count=s.m=="rubber" and 64 or 48
  for i=0,count-1 do
   local a=i*math.pi*2/count;local b=(i+1)*math.pi*2/count
   local function point(t)
    if front then return center+Vector3.new(0,math.sin(t),math.cos(t))*s.major*SCALE end
    return center+Vector3.new(math.cos(t),math.sin(t),0)*s.major*SCALE
   end
   rod(s.n,point(a),point(b),s.tube,s.m)
  end
 elseif s.t=="text" then
  local cf=CFrame.new(vec(s.p))
  if s.side=="right" then cf=cf*CFrame.Angles(0,math.pi,0)
  elseif s.side=="front" then cf=cf*CFrame.Angles(0,-math.pi/2,0)
  elseif s.side=="rear" then cf=cf*CFrame.Angles(0,math.pi/2,0)
  elseif s.side=="wind" then cf=cf*CFrame.Angles(0,-math.pi/2,0)*CFrame.Angles(-.74,0,0) end
  local p=part(s.n,Vector3.new(s.w*SCALE,s.h*SCALE,.012),cf,s.m)
  p.Transparency=1;p.CastShadow=false
  local gui=Instance.new("SurfaceGui");gui.Name="Livery";gui.Face=Enum.NormalId.Back
  gui.CanvasSize=Vector2.new(1024,256);gui.LightInfluence=0;gui.Parent=p
  -- Back face points local +Z, matching the HTML text plane.
  local label=Instance.new("TextLabel");label.Size=UDim2.fromScale(1,1)
  label.BackgroundTransparency=1;label.Text=s.text;label.TextColor3=colors[s.m]
  label.Font=Enum.Font.GothamBlack;label.TextScaled=true;label.Parent=gui
 end
